import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Warum startet das Dashboard nicht?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/04.fehlerbehebung/01.dashboard-startet-nicht.md"},"headers":[],"relativePath":"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","filePath":"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","lastUpdated":1795388431000}'),o={name:"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md"};function s(r,e,d,l,h,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="warum-startet-das-dashboard-nicht" tabindex="-1">Warum startet das Dashboard nicht? <a class="header-anchor" href="#warum-startet-das-dashboard-nicht" aria-label="Permalink to &quot;Warum startet das Dashboard nicht?&quot;">​</a></h1><p><a id="dashboard-not-start-pillow-esphome"></a></p><h2 id="warum-startet-das-dashboard-nicht-pillow-esphome-versionskonflikt" tabindex="-1">Warum startet das Dashboard nicht (Pillow-/ESPHome-Versionskonflikt)? <a class="header-anchor" href="#warum-startet-das-dashboard-nicht-pillow-esphome-versionskonflikt" aria-label="Permalink to &quot;Warum startet das Dashboard nicht (Pillow-/ESPHome-Versionskonflikt)?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist passen ESPHome-Version und Pillow-Version nicht zusammen. Stell in den Instanz-Einstellungen wieder ESPHome <code>2026.6.5</code> und Pillow <code>12.2.0</code> ein und speichere. Diese Kombination lässt sich zuverlässig installieren.</p><p>Der Adapter installiert für das Dashboard genau die beiden Versionen, die du einstellst: <code>esphome==&lt;Version&gt;</code> und <code>pillow==&lt;Version&gt;</code>. Er gleicht sie nicht miteinander ab. Verlangt die gewählte ESPHome-Version eine andere Pillow-Version, bricht die Installation ab und das Dashboard startet nicht. Im Log steht dann „Fatal error starting ESPHomeDashboard“, oft mit einem Hinweis von pip, welche Pillow-Version ESPHome verlangt.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne im Admin das Log der Instanz <code>esphome.0</code> und such nach „Fatal error starting ESPHomeDashboard“. Steht dort eine Pillow-Version, die ESPHome verlangt, merk sie dir.</li><li>Öffne die Instanz-Einstellungen, Reiter „ESPHome-Dashboard“.</li><li>Willst du deine ESPHome-Version behalten, wähle bei „Pillow-Version“ die Version, die pip im Log verlangt. Sonst stell beide Felder auf die Voreinstellung: „ESPHome Dashboard-Version“ <code>2026.6.5</code> und „Pillow-Version“ <code>12.2.0</code>.</li><li>Speichere. Die Instanz startet neu und richtet die Python-Umgebung neu ein.</li><li>Es hat geklappt, wenn im Log „Starting ESPHome Dashboard“ steht und der Dashboard-Tab lädt.</li></ol><p>Startet es danach immer noch nicht, ist oft die Python-Umgebung selbst beschädigt, zum Beispiel nach einem abgebrochenen Download. Dann hilft <a href="#clear-autopy-cache-if-python">Wie leere ich den autopy-Cache, wenn die Python-Umgebung defekt ist?</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Steht „Always last available“ in einem der beiden Felder, kann jedes neue ESPHome- oder Pillow-Release das Dashboard ohne dein Zutun lahmlegen. Wähle feste Versionen.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version?</a></p><p><a id="about-please-install-pillow-python"></a></p><h2 id="was-tun-bei-please-install-the-pillow-python-package" tabindex="-1">Was tun bei &quot;Please install the pillow python package&quot;? <a class="header-anchor" href="#was-tun-bei-please-install-the-pillow-python-package" aria-label="Permalink to &quot;Was tun bei &quot;Please install the pillow python package&quot;?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="log-only-say-esphome-dashboard"></a></p><h2 id="warum-steht-nur-esphome-dashboard-stopped-im-log-und-startet-nach-einer-neuen-esphome-version-nicht-mehr" tabindex="-1">Warum steht nur &quot;ESPHome Dashboard stopped&quot; im Log und startet nach einer neuen ESPHome-Version nicht mehr? <a class="header-anchor" href="#warum-steht-nur-esphome-dashboard-stopped-im-log-und-startet-nach-einer-neuen-esphome-version-nicht-mehr" aria-label="Permalink to &quot;Warum steht nur &quot;ESPHome Dashboard stopped&quot; im Log und startet nach einer neuen ESPHome-Version nicht mehr?&quot;">​</a></h2><p><strong>Kurz:</strong> ESPHome ab Version 2026.7 lässt sich mit v1.0.1 bei vielen Nutzern nicht installieren oder starten. Stell „ESPHome Dashboard-Version“ auf <code>2026.6.5</code> und „Pillow-Version“ auf <code>12.2.0</code> und speichere.</p><p>Dass im Log nur „ESPHome Dashboard stopped“ steht, liegt am Adapter: In v1.0.1 schreibt er nur Meldungen des Dashboards ins Log, die „INFO“ enthalten. Fehlermeldungen des Dashboards und den Grund für das Beenden siehst du deshalb nicht. Das ist eine bekannte Einschränkung.</p><h3 id="so-gehst-du-vor-1" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor-1" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von ESPHome, Reiter „ESPHome-Dashboard“.</li><li>Steht bei „ESPHome Dashboard-Version“ „Always last available“ oder eine Version ab 2026.7, wähle <code>2026.6.5</code>.</li><li>Wähle bei „Pillow-Version“ <code>12.2.0</code>.</li><li>Speichere. Die Instanz startet neu und installiert die Versionen. Das dauert einige Minuten.</li><li>Es hat geklappt, wenn im Log „Starting ESPHome Dashboard“ steht und danach kein „ESPHome Dashboard stopped“ mehr folgt.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Willst du sehen, warum das Dashboard stoppt, stell die Protokollstufe der Instanz auf „debug“. Dann erscheinen alle Meldungen des Dashboards mit „INFO“ im Log, nicht nur die Startmeldung. Fehlermeldungen ohne „INFO“ fehlen in v1.0.1 aber auch dann.</p></div><p>Hast du „Always last available“ gewählt, folgt das Dashboard bei jedem Start dem neuesten ESPHome-Release. Erscheint eine neue Version, die sich nicht installieren lässt, hört das Dashboard ohne dein Zutun auf zu laufen. Der Adapter warnt beim Start im Log: „ESPHome Dashboard version is set to &quot;Always last available&quot;“.</p><p>Bei Updates auf v1.0.0 hat der Adapter „Always last available“ einmalig auf <code>2026.6.5</code> und <code>12.2.0</code> umgestellt. Hast du danach wieder „Always last available“ gewählt, bleibt das so.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version?</a></p><p><a id="clear-autopy-cache-if-python"></a></p><h2 id="wie-leere-ich-den-autopy-cache-wenn-die-python-umgebung-defekt-ist" tabindex="-1">Wie leere ich den autopy-Cache, wenn die Python-Umgebung defekt ist? <a class="header-anchor" href="#wie-leere-ich-den-autopy-cache-wenn-die-python-umgebung-defekt-ist" aria-label="Permalink to &quot;Wie leere ich den autopy-Cache, wenn die Python-Umgebung defekt ist?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="about-permission-denied-missing-yaml"></a></p><h2 id="was-tun-bei-permission-denied-oder-fehlendem-yaml-ordner" tabindex="-1">Was tun bei Permission denied oder fehlendem YAML-Ordner? <a class="header-anchor" href="#was-tun-bei-permission-denied-oder-fehlendem-yaml-ordner" aria-label="Permalink to &quot;Was tun bei Permission denied oder fehlendem YAML-Ordner?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',29)])])}const p=a(o,[["render",s]]);export{m as __pageData,p as default};
